    correction: [{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">-(x - y + 5) = -x + y - 5</span>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [-x + y - 5 + x - 3] = -y + 5 + 3</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [1 + y - x + 3] = -1 - y + x - 3</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -4 - y + 5 + 3 - 1 - y + x - 3 + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = x + (-y - y) + (-4 + 5 + 3 - 1 - 3 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 5 + 3 - 1 - 3 + 1 = 1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - 2y + 1</span>"}],
